ALTER TABLE "planning"."occurrence_actual_link" DROP CONSTRAINT "ck_occurrence_link_amount";--> statement-breakpoint
ALTER TABLE "planning"."recurrence_version" DROP CONSTRAINT "ck_recurrence_grammar";--> statement-breakpoint
