ALTER TABLE "planning"."occurrence_actual_link" ADD CONSTRAINT "ck_occurrence_link_amount" CHECK (COALESCE("planning"."occurrence_actual_link"."linked_minor">0 AND "planning"."occurrence_actual_link"."linked_minor"<=100000000000 AND (("planning"."occurrence_actual_link"."reverses_link_id" IS NULL AND "planning"."occurrence_actual_link"."reason" IS NULL) OR ("planning"."occurrence_actual_link"."reverses_link_id" IS NOT NULL AND char_length(btrim("planning"."occurrence_actual_link"."reason")) BETWEEN 1 AND 2000)),false));--> statement-breakpoint
ALTER TABLE "planning"."recurrence_version" ADD CONSTRAINT "ck_recurrence_grammar" CHECK (COALESCE(("planning"."recurrence_version"."frequency"='daily' AND "planning"."recurrence_version"."interval_count" BETWEEN 1 AND 365 AND "planning"."recurrence_version"."weekdays" IS NULL AND "planning"."recurrence_version"."day_of_month" IS NULL AND "planning"."recurrence_version"."short_month_policy" IS NULL) OR ("planning"."recurrence_version"."frequency"='weekly' AND "planning"."recurrence_version"."interval_count" BETWEEN 1 AND 52 AND cardinality("planning"."recurrence_version"."weekdays") BETWEEN 1 AND 7 AND "planning"."recurrence_version"."weekdays"<@ARRAY[1,2,3,4,5,6,7] AND "planning"."recurrence_version"."day_of_month" IS NULL AND "planning"."recurrence_version"."short_month_policy" IS NULL) OR ("planning"."recurrence_version"."frequency"='monthly' AND "planning"."recurrence_version"."interval_count" BETWEEN 1 AND 120 AND "planning"."recurrence_version"."weekdays" IS NULL AND "planning"."recurrence_version"."day_of_month" BETWEEN 1 AND 31 AND "planning"."recurrence_version"."short_month_policy" IN ('last_valid_day','skip')),false));--> statement-breakpoint
ALTER TABLE "planning"."recurrence_version" ADD CONSTRAINT "ck_recurrence_revision" CHECK (COALESCE(("planning"."recurrence_version"."version_no"=1 AND "planning"."recurrence_version"."previous_version_id" IS NULL AND "planning"."recurrence_version"."reason" IS NULL) OR ("planning"."recurrence_version"."version_no">1 AND "planning"."recurrence_version"."previous_version_id" IS NOT NULL AND char_length(btrim("planning"."recurrence_version"."reason")) BETWEEN 1 AND 2000),false));